('110','2026-10',47,'Ingresos','Ingresos brutos de actividades ordinarias','Registrar detalle de las operaciones del concepto; verificar reconocimiento fiscal y no duplicar consignaciones o transferencias propias.','ET 26; 27/28 y norma específica según operación','Distinguir ventas, servicios y rendimientos de su soporte original.','Factura, contrato, certificado o extracto según corresponda.','ingreso',''),
('110','2026-10',48,'Ingresos','Ingresos financieros','Registrar detalle de las operaciones del concepto; verificar reconocimiento fiscal y no duplicar consignaciones o transferencias propias.','ET 26; 27/28 y norma específica según operación','Distinguir ventas, servicios y rendimientos de su soporte original.','Factura, contrato, certificado o extracto según corresponda.','ingreso',''),
